const fs=require('fs'),path=require('path'),crypto=require('crypto'),assert=require('assert/strict'),png=require('./png.cjs');
(async()=>{const url='http://127.0.0.1:8765/api/project?id=scene-inn-20261119',r=await fetch(url);assert(r.ok);const raw=Buffer.from(await r.arrayBuffer()),p=JSON.parse(raw),dest='C:/Users/Administrator/Desktop/最后/游戏资产/游戏内部/旅馆',out=path.resolve('output/inn-export-'+Date.now()),backup=path.join(out,'originals');fs.mkdirSync(backup,{recursive:true});fs.writeFileSync(path.join(out,'project.json'),raw);const hash=b=>crypto.createHash('sha256').update(b).digest('hex'),unchanged=new Map(fs.readdirSync(dest).filter(n=>n.endsWith('.import')||['table.png','cabinet 1.png'].includes(n)).map(n=>[n,hash(fs.readFileSync(path.join(dest,n)))]));const records=[];
for(const s of p.spriteSheets){if(s.name.startsWith('比例'))continue;assert(!/[\\/:*?"<>|]/.test(s.name));const name=s.name+'.png',target=path.join(dest,name),b=Buffer.from(s.imageDataURL.split(',')[1],'base64'),im=png.decode(b);let originalSHA256=null;if(fs.existsSync(target)){const old=fs.readFileSync(target),prev=png.decode(old);assert.equal(prev.width,im.width,name);assert.equal(prev.height,im.height,name);fs.writeFileSync(path.join(backup,name),old);originalSHA256=hash(old);}fs.writeFileSync(target,b);assert.equal(hash(fs.readFileSync(target)),hash(b));records.push({name,width:im.width,height:im.height,originalSHA256,exportSHA256:hash(b)});}
for(const [name,h] of unchanged)assert.equal(hash(fs.readFileSync(path.join(dest,name))),h,name);
fs.writeFileSync(path.join(out,'verification.json'),JSON.stringify({dest,sourceETag:r.headers.get('etag'),sourceSHA256:hash(raw),exported:records.length,allReadbackVerified:true,untouchedFiles:[...unchanged.keys()],records},null,2));assert.equal(JSON.parse(fs.readFileSync(path.join(out,'verification.json'))).exported,24);console.log(JSON.stringify({dest,backup,exported:records.length,verified:true},null,2));})().catch(e=>{console.error(e);process.exitCode=1});
